// Generate NUL-terminated input strings via the fuzzer runtime.
std::string s_str = FUZZ_PARAM_STR();
std::string s_from = FUZZ_PARAM_STR();
std::string s_to = FUZZ_PARAM_STR();

// Enforce documented requirements: parameters must be valid C strings.
// FUZZ_PARAM_STR() guarantees non-empty and NUL-terminated via c_str().
// Behavior for empty "from" is unspecified; bail out to avoid UB.
if (s_from.empty()) { FUZZ_BAIL(); }

const char *str = s_str.c_str();
const char *from = s_from.c_str();
const char *to = s_to.c_str();

// Call target function. Ownership of the returned buffer is unknown; do not free it here.
char *out = repl_str(str, from, to);

// If the implementation signals failure by returning NULL, bail.
if (!out) { FUZZ_BAIL(); }

// Optionally sanity-check that the output looks like a C string by probing for a NUL
// within a bounded window; skip strict assertions since allocation/ownership are unknown.
// No further actions to avoid leaks/double-frees; the harness runtime will reclaim process memory on reset.

// Validation: Inputs are valid NUL-terminated strings; we avoid empty "from"; we accept either success (non-NULL) or bail on NULL.

// Prepare stream with random file data.
const char *path = FUZZ_PARAM_FILENAME();
FILE *stream = fopen(path, "rb");
if (!stream) { FUZZ_BAIL(); }

// Decide initial buffer state: either let getdelim allocate, or provide a preallocated buffer.
unsigned int choice = *FUZZ_PARAM(unsigned int);
char *lineptr_local = nullptr;
size_t n_local = 0;

if ((choice & 1u) != 0u) {
    // Provide an initial buffer in [1, 1024] bytes.
    size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
    lineptr_local = (char *)malloc(cap);
    if (!lineptr_local) { fclose(stream); FUZZ_BAIL(); }
    // Fill with random data to catch code that assumes initial contents.
    for (size_t i = 0; i < cap; ++i) { lineptr_local[i] = (char)(*FUZZ_PARAM(unsigned int) & 0xFF); }
    // Ensure it's still a valid C buffer by keeping a trailing NUL somewhere.
    lineptr_local[cap - 1] = '\0';
    n_local = cap;
}

char *lp = lineptr_local;
size_t n = n_local;

// Choose a delimiter; only low-order unsigned char is used.
int delimiter = (int)(*FUZZ_PARAM(unsigned int) & 0xFF);

// Call target function.
ssize_t r = getdelim(&lp, &n, delimiter, stream);

// Postconditions and cleanup.
if (r >= 0) {
    // On success, lp must be non-NULL and the buffer must be NUL-terminated at index r.
    FUZZ_ASSERT(lp != nullptr, "getdelim succeeded but *lineptr is NULL");
    FUZZ_ASSERT(lp[(size_t)r] == '\0', "getdelim result is not NUL-terminated at reported length");
}

// Free any allocated buffer (either our own or the one allocated/realloc'd by getdelim on success).
if (lp) { free(lp); }

fclose(stream);

// Validation: Enforced non-NULL pointers, valid FILE*, and delimiter constraints; asserted POSIX postconditions on success and cleaned up allocations/stream.

// Prepare stream with random file data.
const char *path = FUZZ_PARAM_FILENAME();
FILE *stream = fopen(path, "rb");
if (!stream) { FUZZ_BAIL(); }

// Decide initial buffer state: either let getline allocate, or provide a preallocated buffer.
unsigned int choice = *FUZZ_PARAM(unsigned int);
char *lineptr_local = nullptr;
size_t n_local = 0;

if ((choice & 1u) != 0u) {
    // Provide an initial buffer in [1, 1024] bytes.
    size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
    lineptr_local = (char *)malloc(cap);
    if (!lineptr_local) { fclose(stream); FUZZ_BAIL(); }
    for (size_t i = 0; i < cap; ++i) { lineptr_local[i] = (char)(*FUZZ_PARAM(unsigned int) & 0xFF); }
    lineptr_local[cap - 1] = '\0';
    n_local = cap;
}

char *lp = lineptr_local;
size_t n = n_local;

// Call target function.
ssize_t r = getline(&lp, &n, stream);

// Postconditions and cleanup.
if (r >= 0) {
    FUZZ_ASSERT(lp != nullptr, "getline succeeded but *lineptr is NULL");
