import random
import os
import struct

# Generator for interesting arbitrary binary file data aimed at exercising getdelim
# behaviors with various delimiters and buffer growth patterns. The file
# may contain many lines separated by a wide variety of delimiter bytes,
# including edge cases like NUL, newline, high-bit values, and long runs
# without delimiters to force realloc/growth.

MAX_SIZE = 4096

COMMON_DELIMS = [
    0x0A,  # \n
    0x00,  # NUL
    0x0D,  # \r
    0x09,  # \t
    0xFF,  # 255
    0x7F,  # DEL
    0x3A,  # ':'
    0x7C,  # '|'
    0x2C,  # ','
]

PRINTABLES = [i for i in range(0x20, 0x7F)]


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _chunk_plain(rng: random.Random, length: int) -> bytes:
    # Mostly printable with occasional binary noise
    out = bytearray()
    for _ in range(length):
        if rng.random() < 0.10:
            out.append(rng.randrange(256))
        else:
            out.append(rng.choice(PRINTABLES))
    return bytes(out)


def _chunk_repeated(rng: random.Random, byte_val: int, length: int) -> bytes:
    return bytes([byte_val]) * length


def _chunk_increasing(rng: random.Random, length: int, start: int | None = None) -> bytes:
    if start is None:
        start = rng.randrange(256)
    return bytes(((start + i) & 0xFF) for i in range(length))


def _chunk_patterned(rng: random.Random, length: int) -> bytes:
    # Mix of small integers, UTF-8-like, and boundary bytes
    pattern = [0x00, 0xFF, 0x01, 0x7F, 0x80, 0xC2, 0xA9, 0xE2, 0x82, 0xAC]
    out = bytearray()
    for _ in range(length):
        if rng.random() < 0.6:
            out.append(rng.choice(pattern))
        else:
            out.append(rng.randrange(256))
    return bytes(out)


def _with_delimiter(rng: random.Random, data: bytes, delim: int | None) -> bytes:
    if delim is None:
        return data
    return data + bytes([delim])


def _make_section(rng: random.Random, target_delim: int | None, max_payload: int) -> bytes:
    # Build one or more chunks and optionally terminate with target_delim.
    # Lengths chosen to cover small, medium, and large reads.
    out = bytearray()

    # Number of chunks within a section
    chunks = rng.randint(1, 4)
    for i in range(chunks):
        # Choose chunk strategy
        strategy = rng.choice([
            'plain', 'repeated', 'increasing', 'patterned', 'random'
        ])
        # Choose size profiles; include sizes around typical realloc thresholds
        size_profile = rng.choice([
            rng.randint(0, 8),        # tiny
            rng.randint(9, 32),       # small
            rng.randint(33, 256),     # medium
            rng.randint(257, 1024),   # large
        ])
        size = min(size_profile, max_payload - len(out))
        if size <= 0:
            break

        if strategy == 'plain':
            out += _chunk_plain(rng, size)
        elif strategy == 'repeated':
            out += _chunk_repeated(rng, rng.randrange(256), size)
        elif strategy == 'increasing':
            out += _chunk_increasing(rng, size)
        elif strategy == 'patterned':
            out += _chunk_patterned(rng, size)
        else:
            out += _rand_bytes(rng, size)

    # Occasionally insert the delimiter within payload to create multiple reads
    if target_delim is not None and len(out) > 0 and rng.random() < 0.3:
        insert_pos = rng.randrange(0, len(out))
        out[insert_pos:insert_pos] = bytes([target_delim])

    # Optionally end section with delimiter to finalize the line for that delimiter
    if rng.random() < 0.8:
        out = bytearray(_with_delimiter(rng, bytes(out), target_delim))

    # Occasionally inject a different delimiter inside to vary behavior when
    # the fuzzer chooses a non-matching delimiter.
    if rng.random() < 0.25:
        other = rng.choice(COMMON_DELIMS)
        if target_delim is None or other != target_delim:
            if len(out) < max_payload:
                out += bytes([other])

    return bytes(out[:max_payload])


def _build_file(rng: random.Random) -> bytes:
    # Choose a primary delimiter we will feature in the file, but also include
    # other delimiters to exercise mismatch cases.
    primary_delim = rng.choice(COMMON_DELIMS + [rng.randrange(256)])

    # Plan total size under MAX_SIZE with some variability
    target_size = rng.randint(128, MAX_SIZE)

    out = bytearray()

    # Header: include hints and edge bytes to test initial reads
    header_modes = [
        b"",                       # no header
        b"# header\n",             # text header
        b"\x00\x00\x00\x00",       # leading NULs
        b"BOM\xEF\xBB\xBF",         # pseudo-BOM tag
        b"LEN",                      # token
    ]
    header = rng.choice(header_modes)
    out += header

    # Optionally include a length-prefixed binary block to create long segments
    if rng.random() < 0.5:
        block_len = rng.randint(32, 512)
        # 4-byte little-endian length then content without the primary delimiter
        out += struct.pack('<I', block_len)
        block = bytearray(_rand_bytes(rng, block_len))
        # Reduce chance of accidental primary delimiter to create long read regions
        for i in range(len(block)):
            if block[i] == primary_delim and rng.random() < 0.85:
                block[i] = (block[i] + 1) & 0xFF
        out += block
        # Sometimes terminate with the primary delimiter
        if rng.random() < 0.7:
            out += bytes([primary_delim])

    # Generate multiple sections aimed at mixing delimiter presence and absence
    while len(out) < target_size:
        # Sometimes choose no delimiter to force EOF-terminated line
        use_delim = primary_delim if rng.random() < 0.75 else None
        remaining = target_size - len(out)
        sec = _make_section(rng, use_delim, max_payload=min(1024, remaining))
        if not sec:
            break
        out += sec

        # Occasionally add very long delimiter-free region to test growth
        if rng.random() < 0.2 and len(out) < target_size:
            long_len = min(rng.randint(256, 1200), target_size - len(out))
            # Avoid primary delimiter deliberately
            chunk = bytearray(_rand_bytes(rng, long_len))
            if use_delim is not None:
                for i in range(len(chunk)):
                    if chunk[i] == use_delim and rng.random() < 0.9:
                        chunk[i] = (chunk[i] + 2) & 0xFF
            out += chunk

            # Maybe finalize with a different delimiter
            if rng.random() < 0.5:
                out += bytes([rng.choice(COMMON_DELIMS)])

    # Footer: sometimes ensure the file ends without a trailing delimiter
    if rng.random() < 0.5 and len(out) > 0 and out[-1] in COMMON_DELIMS:
        out.pop()

    # Ensure not exceeding MAX_SIZE
    return bytes(out[:MAX_SIZE])


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return _build_file(rng)
